# -*- coding: utf-8 -*-
"""第26–30章 海外意外就医 / 跨国离婚 / 合伙公司治理 / 破产清算 / 法律域外效力。"""

def E(n, title, tags, cost, plain, gain, ev, src, note="", exp=""):
    exp = (exp or "").strip()
    if exp.startswith("解释："):
        exp = exp[len("解释："):]
    return dict(n=n, title=title, tags=tags, cost=cost, plain=plain,
                gain=gain, ev=ev, src=src, note=note, exp=exp)

